import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as a,o,c as r,ak as n}from"./chunks/framework.DC-k2h36.js";const i="/projects/esp32Sensor/en/latest/assets/1.BjnUVtDF.webp",s="/projects/esp32Sensor/en/latest/assets/2.CjM1TtMO.webp",l="/projects/esp32Sensor/en/latest/assets/3.ZKMHGM-F.webp",c="/projects/esp32Sensor/en/latest/assets/4.Bj09Btda.webp",d="/projects/esp32Sensor/en/latest/assets/5.B5vzjcMf.webp",b=JSON.parse('{"title":"9. Acceleration Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/9. Acceleration Sensor.md","filePath":"docs/9. Acceleration Sensor.md"}'),h={name:"docs/9. Acceleration Sensor.md"};function p(g,e,m,u,_,x){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_9-acceleration-sensor" tabindex="-1">9. Acceleration Sensor <a class="header-anchor" href="#_9-acceleration-sensor" aria-label="Permalink to &quot;9. Acceleration Sensor&quot;">​</a></h1><h2 id="_9-1-introduction" tabindex="-1">9.1 Introduction <a class="header-anchor" href="#_9-1-introduction" aria-label="Permalink to &quot;9.1 Introduction&quot;">​</a></h2><p>The acceleration sensor is a versatile motion-sensing module widely applied in handheld gaming devices, 3D controllers, and portable navigation equipment. Featuring an integrated gyroscope core, the sensor detects tilt angles, rotational speed, and movement orientation.</p><img loading="lazy" height="1156" width="1156" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_9-2-technical-specifications" tabindex="-1">9.2 Technical Specifications <a class="header-anchor" href="#_9-2-technical-specifications" aria-label="Permalink to &quot;9.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Accelerometer range</td><td style="text-align:center;">±2, ±4, ±8, ±16 g</td></tr><tr><td style="text-align:center;">Gyroscope range</td><td style="text-align:center;">±250, ±500, ±1,000, ±2,000°/s</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 16.7 mm</td></tr></tbody></table><h2 id="_9-3-hands-on-project" tabindex="-1">9.3 Hands-On Project <a class="header-anchor" href="#_9-3-hands-on-project" aria-label="Permalink to &quot;9.3 Hands-On Project&quot;">​</a></h2><h3 id="_9-3-1-project-overview" tabindex="-1">9.3.1 Project Overview <a class="header-anchor" href="#_9-3-1-project-overview" aria-label="Permalink to &quot;9.3.1 Project Overview&quot;">​</a></h3><p>This project uses the IMU acceleration sensor to read tilt angles along the X-axis and Y-axis, outputting the angle data via the serial port. Rotating or tilting the sensor updates the corresponding angle values dynamically, illustrating IMU sensor initialization, tilt angle acquisition, and serial print programming logic.</p><h3 id="_9-3-2-hardware-wiring" tabindex="-1">9.3.2 Hardware Wiring <a class="header-anchor" href="#_9-3-2-hardware-wiring" aria-label="Permalink to &quot;9.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the acceleration sensor to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="620" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_9-3-3-adding-extensions" tabindex="-1">9.3.3 Adding Extensions <a class="header-anchor" href="#_9-3-3-adding-extensions" aria-label="Permalink to &quot;9.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>IMU sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_9-3-4-complete-program-and-analysis" tabindex="-1">9.3.4 Complete Program and Analysis <a class="header-anchor" href="#_9-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;9.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon start-up, the hardware port of the acceleration sensor is initialized to port P1, followed by a 2 s delay to complete sensor calibration preparation.</p></li><li><p>Inside the main program loop, the X-axis and Y-axis angle values of the IMU sensor are continuously read.</p></li><li><p>The acquired X-axis and Y-axis angle values are output via the serial port.</p></li><li><p>A 0.5 s delay is executed at the end of each loop iteration to lower the data refresh frequency and stabilize serial output.</p></li></ol><img loading="lazy" height="539" width="699" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/09 Acceleration Sensor.sb3</a>.</strong></p></div><h3 id="_9-3-5-program-upload" tabindex="-1">9.3.5 Program Upload <a class="header-anchor" href="#_9-3-5-program-upload" aria-label="Permalink to &quot;9.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_9-3-6-program-outcome" tabindex="-1">9.3.6 Program Outcome <a class="header-anchor" href="#_9-3-6-program-outcome" aria-label="Permalink to &quot;9.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, check the serial monitor in the lower-right corner of the software. Tilting or rotating the acceleration sensor updates the X-axis and Y-axis angles in real time, clearly showing how the readings change with the sensor&#39;s orientation.</p><img loading="lazy" height="903" width="1205" src="'+d+'" class="common_img" style="width:500px;">',26)])])}const w=a(h,[["render",p]]);export{b as __pageData,w as default};
